const express = require('express');
const fetch = require('node-fetch');

const app = express();
app.use(express.json());

app.post('/webhook/purchase', async (req, res) => {
  const { purchaseId, customerEmail, productName, amount } = req.body;

  if (!purchaseId || !customerEmail || !productName || !amount) {
    return res.status(400).json({
      error: "Missing required fields",
      required: ["purchaseId", "customerEmail", "productName", "amount"]
    });
  }

  try {
    const response = await fetch('https://staging.crossmint.com/api/2022-06-09/collections/default/nfts', {
      method: 'POST',
      headers: {
        'X-API-KEY': process.env.CROSSMINT_API_KEY || '',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        recipient: `email:${customerEmail}:polygon-amoy`,
        metadata: {
          name: `Receipt: ${productName}`,
          description: `Proof of purchase for order ${purchaseId}`,
          image: "https://example.com/receipt.png"
        }
      })
    });

    let data = {};
    if (response.ok) {
      data = await response.json().catch(() => ({}));
    } else {
      data = await response.json().catch(() => ({}));
      console.error('Crossmint API error:', response.status, data);
    }

    const actionId = data.id || "mock-action";

    res.json({
      status: "receipt_minted",
      purchaseId,
      actionId
    });
  } catch (error) {
    console.error('Error minting NFT:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: "ok" });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

