const { spawn } = require('child_process');
const fetch = require('node-fetch');
const fs = require('fs');

async function runTest() {
  const server = spawn('node', ['/home/user/webhook_server.js'], {
    env: { ...process.env, CROSSMINT_API_KEY: 'test_key' }
  });

  server.stdout.on('data', (data) => console.log(`Server: ${data}`));
  server.stderr.on('data', (data) => console.error(`Server Error: ${data}`));

  // Wait a bit for server to start
  await new Promise(resolve => setTimeout(resolve, 2000));

  let healthCheck = false;
  let webhookResponse = null;

  try {
    const healthRes = await fetch('http://localhost:3000/health');
    if (healthRes.ok) {
      const data = await healthRes.json();
      healthCheck = data.status === 'ok';
    }
  } catch (e) {
    console.error('Health check failed', e);
  }

  try {
    const webhookRes = await fetch('http://localhost:3000/webhook/purchase', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        purchaseId: 'test-123',
        customerEmail: 'test@example.com',
        productName: 'Premium Widget',
        amount: 99.99
      })
    });
    webhookResponse = await webhookRes.json().catch(() => ({ error: 'Failed to parse JSON response' }));
  } catch (e) {
    console.error('Webhook failed', e);
    webhookResponse = { error: e.message };
  }

  const report = {
    health_check: healthCheck,
    webhook_response: webhookResponse
  };

  fs.writeFileSync('/home/user/webhook_test_report.json', JSON.stringify(report, null, 2));

  server.kill();
  process.exit(0);
}

runTest();

